import React, { useState, useRef, useEffect } from 'react';

export default function MenuOption(){
    const [open, setOpen] = useState(false);
    const ref = useRef(null);

    useEffect(()=>{
        function onDoc(e){
            if(ref.current && !ref.current.contains(e.target)) setOpen(false);
        }
        document.addEventListener('mousedown', onDoc);
        return ()=>document.removeEventListener('mousedown', onDoc);
    },[]);

    return (
        <div className="menu-option" ref={ref}>
            <button className="gear-button" onClick={()=>setOpen(o=>!o)} aria-label="options">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M12 15.5A3.5 3.5 0 1 0 12 8.5a3.5 3.5 0 0 0 0 7z" fill="currentColor" />
                    <path d="M19.4 15a1 1 0 0 0 .2 1.1l.1.1a1 1 0 0 1-1.4 1.4l-.1-.1a1 1 0 0 0-1.1-.2 7 7 0 0 1-1.6.9 1 1 0 0 0-.6 1v.2a1 1 0 0 1-2 0v-.2a1 1 0 0 0-.6-1 7 7 0 0 1-1.6-.9 1 1 0 0 0-1.1.2l-.1.1A1 1 0 0 1 5.3 16l.1-.1a1 1 0 0 0 .2-1.1 7 7 0 0 1-.9-1.6 1 1 0 0 0-1-.6H3.4a1 1 0 0 1 0-2h.2a1 1 0 0 0 1-.6c.2-.6.5-1.2.9-1.6a1 1 0 0 0-.2-1.1L5.3 6.3A1 1 0 0 1 6.7 4.9l.1.1a1 1 0 0 0 1.1.2c.6-.2 1.2-.5 1.6-.9a1 1 0 0 0 .6-1V3.4a1 1 0 0 1 2 0v.2c0 .3.2.6.6 1 .4.4 1 .7 1.6.9.5.2.8 0 1.1-.2l.1-.1A1 1 0 0 1 18 6.7l-.1.1a1 1 0 0 0-.2 1.1c.2.6.5 1.2.9 1.6.2.3.5.5.8.6h.2a1 1 0 0 1 0 2h-.2c-.4 0-.6.2-.8.6-.4.5-.7 1-1 1.6z" fill="currentColor" />
                </svg>
            </button>
            {open && (
                <div className="menu-dropdown">
                    <button className="menu-item">Option 1</button>
                    <button className="menu-item">Option 2</button>
                    <button className="menu-item">Fermer</button>
                </div>
            )}
        </div>
    );
}
